import pandas as pd

def clean(df):
    df = df.copy()
    # standardise island label variants
    island_map = {"Torgerson": "Torgersen", "Bisco": "Biscoe"}
    if "island" in df.columns:
        df["island"] = df["island"].astype(str).str.strip()
        df["island"] = df["island"].replace(island_map)
    # standardise sex label variants
    if "sex" in df.columns:
        df["sex"] = df["sex"].astype(str).str.strip().str.lower()
    # parse numeric columns that are stored as text
    num_cols = ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "body_mass_g", "year"]
    for col in num_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col].astype(str).str.replace(",", "", regex=False), errors="coerce")
    # keep id column
    return df

def answer(df):
    dfc = clean(df)
    # filter to Adelie penguins and allowed islands
    allowed_islands = {"Biscoe", "Dream", "Torgersen"}
    adelie = dfc[(dfc["species"] == "Adelie") & (dfc["island"].isin(allowed_islands))]
    # average bill length by island
    grp = adelie.groupby("island")["bill_length_mm"].mean().dropna()
    return {str(k): float(v) for k, v in grp.items()}
